def parse_args(argv):
    help_f = version_f = key_f = full_f = False
    pos = []
    stop = False
    for arg in argv:
        if stop:
            pos.append(arg); continue
        if arg == "--":
            stop = True; continue
        if arg.startswith("--"):
            if arg == "--help": help_f = True
            elif arg == "--version": version_f = True
            elif arg == "--key" or arg == "--keybinding": key_f = True
            elif arg == "--fullscreen": full_f = True
            else: return None
        elif arg.startswith("-") and arg != "-":
            # CLI11-style short option groups. This intentionally makes '-key'
            # invalid because 'e' and 'y' are not defined short options.
            for ch in arg[1:]:
                if ch == 'h': help_f = True
                elif ch == 'v': version_f = True
                elif ch == 'k': key_f = True
                elif ch == 'f': full_f = True
                else: return None
        else:
            pos.append(arg)
    if len(pos) > 1: return None
    return help_f, version_f, key_f, full_f, (pos[0] if pos else None)

def nlohmannish_parse_error(src: str, exc: Exception) -> str:
