    if src == "":
        return "[json.exception.parse_error.101] parse error at line 1, column 1: attempting to parse an empty input; check that your input string or stream contains the expected JSON"
    # Compute a nlohmann-like 1-based line/column at/after the offending token.
    if isinstance(exc, json.JSONDecodeError):
        line, col, pos, msg = exc.lineno, exc.colno, exc.pos
    else:
        line, col, pos, msg = 1, 1, 0, str(exc)
    s = src
    stripped = s.lstrip()
    offset = len(s) - len(stripped)
    # Literal prefixes: nlohmann reports after the consumed invalid prefix.
    if stripped and stripped[0].isalpha():
        m = re.match(r'[A-Za-z]+', stripped)
        lit = m.group(0) if m else stripped[:1]
        p = offset + len(lit)
        line = s.count('\n', 0, p) + 1
        last_nl = s.rfind('\n', 0, p)
        col = p - last_nl
        read = s[offset:p].replace('\n', '<U+000A>')
        return f"[json.exception.parse_error.101] parse error at line {line}, column {col}: syntax error while parsing value - invalid literal; last read: '{read}'"
    if msg.startswith('Expecting property name'):
        ch = s[pos:pos+1]
        if ch == '}':
            return f"[json.exception.parse_error.101] parse error at line {line}, column {col}: syntax error while parsing object key - unexpected '}}'; expected string literal"
        if pos >= len(s):
            # nlohmann points one column after '{'
            return f"[json.exception.parse_error.101] parse error at line {line}, column {col}: syntax error while parsing object key - unexpected end of input; expected string literal"
        return f"[json.exception.parse_error.101] parse error at line {line}, column {col}: syntax error while parsing object key - unexpected '{ch}'; expected string literal"
    if msg.startswith('Expecting value'):
        ch = s[pos:pos+1]
        if ch == '}':
            return f"[json.exception.parse_error.101] parse error at line {line}, column {col}: syntax error while parsing value - unexpected '}}'; expected '[', '{{', or a literal"
        if ch == ']':
            return f"[json.exception.parse_error.101] parse error at line {line}, column {col}: syntax error while parsing value - unexpected ']'; expected '[', '{{', or a literal"
        if pos >= len(s):
            return f"[json.exception.parse_error.101] parse error at line {line}, column {col}: syntax error while parsing value - unexpected end of input; expected '[', '{{', or a literal"
