        read = s[offset:].replace('\n','<U+000A>')
        p = len(s)
        line = s.count('\n', 0, p)+1; col = p - s.rfind('\n', 0, p)
        return f"[json.exception.parse_error.101] parse error at line {line}, column {col}: syntax error while parsing value - invalid string: missing closing quote; last read: '{read}'"
    if msg.startswith("Expecting ',' delimiter"):
        ch = s[pos:pos+1]
        if ch and (ch.isdigit() or ch == '-'):
            return f"[json.exception.parse_error.101] parse error at line {line}, column {col}: syntax error while parsing array - unexpected number literal; expected ']'"
    return f"[json.exception.parse_error.101] parse error at line {line}, column {col}: {msg}"

def load_json(text):
    return json.loads(text)

def json_str(s: str) -> str:
    return json.dumps(s, ensure_ascii=False, separators=(',', ':'))

def scalar_text(v: Any) -> str:
    if v is None: return "null"
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v, str): return json_str(v)
    # Python's JSON float formatting is close to the observed dumper for common cases.
    return json.dumps(v, ensure_ascii=False, separators=(',', ':'))

def color_scalar(v: Any, selected=False) -> str:
    if v is None: col = C_NULL
    elif isinstance(v, bool): col = C_BOOL
    elif isinstance(v, str): col = C_STR
    else: col = C_NUM
    t = scalar_text(v)
    if selected:
        return REV + col + t + NREV + RESET
    return col + t + RESET

def color_key(k: str) -> str:
    return C_KEY + json_str(k) + RESET

def is_table_array(v: Any) -> bool:
    return isinstance(v, list) and len(v) > 0 and all(isinstance(x, dict) for x in v)

def collect_paths(v: Any, path: Path=()) -> List[Path]:
    out=[]
    if isinstance(v, (dict, list)):
        out.append(path)
        if isinstance(v, dict):
            for k in sorted(v.keys()): out += collect_paths(v[k], path+(k,))
        else:
            for i,x in enumerate(v): out += collect_paths(x, path+(i,))
    return out

def get_at(root: Any, path: Path) -> Any:
    v=root
    for p in path: v=v[p]
    return v

class Renderer:
    def __init__(self, data: Any):
        self.data=data
        self.collapsed: Dict[Path,bool] = {}
        self.table: Dict[Path,bool] = {}
        self._init(data, ())
        self.selectables: List[Tuple[str,Path]] = []
        self.selected = 0
    def _init(self, v, path):
        if isinstance(v, list):
            self.collapsed[path] = (path != ())
            for i,x in enumerate(v): self._init(x, path+(i,))
        elif isinstance(v, dict):
            self.collapsed[path] = False
            for k,x in v.items(): self._init(x, path+(k,))
    def selected_item(self):
        if not self.selectables: return ('node', ())
        self.selected=max(0,min(self.selected,len(self.selectables)-1))
        return self.selectables[self.selected]
    def toggle(self):
        typ,path=self.selected_item()
        if typ=='table':
            self.table[path]=not self.table.get(path,False)
            self.collapsed[path]=False
        elif path in self.collapsed:
            self.collapsed[path]=not self.collapsed.get(path,False)
    def expand_deep(self):
        typ,path=self.selected_item();
        if typ=='table': self.table[path]=False
        for p in collect_paths(get_at(self.data,path), path): self.collapsed[p]=False
    def collapse_deep(self):
        typ,path=self.selected_item()
        base=get_at(self.data,path)
        # Keep the selected/root node visible; recursively collapse its children.
        for p in collect_paths(base, path):
            if p != path or path != ():
                self.collapsed[p]=True
        if path == ():
            self.collapsed[path]=False
    def node_token(self, token: str, item: Tuple[str,Path], selected: bool, comma=False) -> str:
        t = token + ("," if comma else "")
        if selected:
            return REV + t + NREV
        return BOLD + t + NBOLD
    def table_label(self, path: Path, selected: bool) -> str:
        label = "(array view)" if self.table.get(path,False) else "(table view)"
        if selected:
            return REV + C_GRAY + label + NREV + RESET
        return C_GRAY + label + RESET
    def render(self) -> Tuple[List[str], List[Tuple[str,Path]]]:
        lines=[]; sels=[]
        def add(line): lines.append(line)
        def selid(typ,path):
            sels.append((typ,path)); return len(sels)-1
        def is_sel(idx): return idx == self.selected
        def rec(v, path: Path, indent: int, prefix: str, last: bool):
            sp="  "*indent
            comma=not last
            if isinstance(v, dict):
                idx=selid('node',path)
                if self.collapsed.get(path,False):
                    add(sp+prefix+self.node_token("{...}",('node',path),is_sel(idx),comma))
                else:
                    add(sp+prefix+self.node_token("{",('node',path),is_sel(idx),False))
                    keys=sorted(v.keys())
                    for n,k in enumerate(keys):
                        rec(v[k], path+(k,), indent+1, color_key(k)+": ", n==len(keys)-1)
                    add(sp+("}" + ("," if comma else "")))
            elif isinstance(v, list):
                idx=selid('node',path)
                tableable=is_table_array(v)
                if self.collapsed.get(path,False):
                    line=sp+prefix+self.node_token("[...]",('node',path),is_sel(idx),comma)
                    if tableable:
                        # The label is independently selectable; right/left can move to it.
                        tidx=selid('table',path)
                        line += "   " + self.table_label(path,is_sel(tidx))
                    add(line)
                elif self.table.get(path,False) and tableable:
                    tidx=selid('table',path)
                    add(sp+prefix+self.table_label(path,is_sel(tidx)) + ("," if comma else ""))
                    for l in self.render_table(v, indent+1): add(l)
                else:
                    add(sp+prefix+self.node_token("[",('node',path),is_sel(idx),False) + ("   "+self.table_label(path,False) if tableable else ""))
                    for i,x in enumerate(v): rec(x, path+(i,), indent+1, "", i==len(v)-1)
                    add(sp+("]," if comma else "]"))
            else:
                idx=selid('node',path)
                add(sp+prefix+color_scalar(v,is_sel(idx))+("," if comma else ""))
        rec(self.data, (), 0, "", True)
        self.selectables=sels
        if self.selected >= len(sels): self.selected=max(0,len(sels)-1)
        return lines,sels
    def render_table(self, arr: List[dict], indent:int) -> List[str]:
        sp="  "*indent
        cols=[]
        for obj in arr:
            for k in sorted(obj.keys()):
                if k not in cols: cols.append(k)
        if not cols: return []
        vals=[]
        widths=[]
        for k in cols:
            maxw=len(k)
            col=[]
            for obj in arr:
                t=scalar_text(obj.get(k)) if not isinstance(obj.get(k), (dict,list)) else ("{...}" if isinstance(obj.get(k),dict) else "[...]" )
                col.append(t); maxw=max(maxw,len(t))
            vals.append(col); widths.append(maxw)
        top="┌"+"┬".join("─"*(w+2) for w in widths)+"┐"
        mid="├"+"┼".join("─"*(w+2) for w in widths)+"┤"
        bot="└"+"┴".join("─"*(w+2) for w in widths)+"┘"
        out=[sp+top]
        out.append(sp+"│"+"│".join(" "+cols[i].ljust(widths[i])+" " for i in range(len(cols)))+"│")
        out.append(sp+mid)
        for r,obj in enumerate(arr):
            cells=[]
            for i,k in enumerate(cols):
                val=obj.get(k)
                if isinstance(val,(dict,list)): cell=("{...}" if isinstance(val,dict) else "[...]")
                else: cell=scalar_text(val)
                cells.append(cell.ljust(widths[i]))
            out.append(sp+C_GRAY+str(r)+RESET+"│"+"│".join(cells[i]+" " for i in range(len(cells)))+"│")
        out.append(sp+bot)
        return out

def visible_len(s: str) -> int:
    return len(ANSI_RE.sub('',s))

def clip_ansi(s: str, width: int) -> str:
    if width <= 0: return ''
    out=[]; n=0; i=0
    while i < len(s):
        if s[i]=='\x1b':
            m=ANSI_RE.match(s,i)
            if m:
                out.append(m.group(0)); i=m.end(); continue
        ch=s[i]
        # crude width: all code points one cell except CJK/box/arrows also treated as one here.
        if n >= width: break
        out.append(ch); n+=1; i+=1
    return ''.join(out)

def prepare_screen(lines: List[str], fullscreen: bool, cols: int, rows: int, prev_height:int=0) -> Tuple[str,int,int]:
    plain_width = max([visible_len(l) for l in lines] + [1])
    if fullscreen:
        width=max(1, cols); height=max(1, rows)
    else:
        width=max(1, min(cols, plain_width)); height=min(len(lines), max(1, rows))
    shown=lines[:height]
    if fullscreen and len(shown)<height: shown += ['']*(height-len(shown))
    out=[]
    if prev_height:
        out.append('\r')
        for _ in range(prev_height): out.append(ESC+'2K'+ESC+'1A')
        out.append(ESC+'2K')
        out.append(ESC+'J'+ESC+'H')
    else:
        out.append('\r'+ESC+'2K')
    for idx,l in enumerate(shown):
        cl=clip_ansi(l,width)
        pad=max(0,width-visible_len(cl))
        out.append(cl + ' '*pad)
        if idx != len(shown)-1: out.append('\r\n')
    # Leave cursor near the top-left like ftxui does. Exact positioning is not vital for usability.
    if height>1: out.append(ESC+f'{height-1}A')
    if width>1: out.append(ESC+f'{width-1}D')
    out.append(ESC+'?25l'+'\x00')
    return ''.join(out), height, width

def read_key(fd: int) -> str:
    while True:
        r,_,_=select.select([fd],[],[],None)
        if not r: continue
        try: b=os.read(fd,1)
        except OSError: time.sleep(0.05); continue
        if not b:
            # The original remains open waiting for a terminal event even when
            # standard input reaches EOF after file input.
            time.sleep(0.1); continue
        c=b.decode('latin1','ignore')
        if c=='\x1b':
            # Gather a short escape sequence if present.
            seq=c
            end=time.time()+0.03
            while time.time()<end:
                r,_,_=select.select([fd],[],[],0.005)
                if not r: break
                try: more=os.read(fd,8)
                except OSError: break
                if not more: break
                seq += more.decode('latin1','ignore')
                if seq.endswith('~') or seq.endswith(('A','B','C','D')): break
            return seq
        return c

def interactive(data: Any, fullscreen: bool) -> int:
    fd=sys.stdin.fileno()
    old=None
    if sys.stdin.isatty():
        try:
            old=termios.tcgetattr(fd); tty.setraw(fd)
        except Exception: old=None
    out=sys.stdout
    size=shutil.get_terminal_size((80,24)); cols=size.columns; rows=size.lines
    try:
        out.write('\x00\x1bP$q q\x1b\\')
        if fullscreen: out.write(ESC+'?1049h')
        out.write(ESC+'?7l'+ESC+'?1000h'+ESC+'?1003h'+ESC+'?1015h'+ESC+'?1006h'+'\x00')
        out.flush()
        r=Renderer(data); prev=0; last_g=False
        while True:
            lines,_=r.render()
            screen,prev,w=prepare_screen(lines,fullscreen,cols,rows,prev)
            out.write(screen); out.flush()
            key=read_key(fd)
            if key in ('q','\x1b'):
                break
            if key in ('j','\x1b[B'):
                r.selected=min(r.selected+1, max(0,len(r.selectables)-1)); last_g=False
            elif key in ('k','\x1b[A'):
                r.selected=max(0,r.selected-1); last_g=False
            elif key in ('h','\x1b[D'):
                r.selected=max(0,r.selected-1); last_g=False
            elif key in ('l','\x1b[C'):
                r.selected=min(r.selected+1, max(0,len(r.selectables)-1)); last_g=False
            elif key in ('\r','\n'):
                r.toggle(); last_g=False
            elif key == '+':
                r.expand_deep(); last_g=False
            elif key == '-':
                r.collapse_deep(); last_g=False
            elif key == 'G' or key.startswith('\x1b[6'):
                r.selected=max(0,len(r.selectables)-1); last_g=False
            elif key == 'g':
                if last_g: r.selected=0; last_g=False
                else: last_g=True
            elif key.startswith('\x1b[5'):
                r.selected=0; last_g=False
            else:
                last_g=False
        # Move to after the inline rendering, leaving it visible.
        if prev:
            out.write(ESC+f'{prev-1}B' if prev>1 else '')
            out.write(ESC+f'{w-1}C' if w>1 else '')
        out.write(ESC+'?1006l'+ESC+'?1015l'+ESC+'?1003l'+ESC+'?1000l'+ESC+'?7h')
        if fullscreen: out.write(ESC+'?1049l')
        out.write(ESC+'?25h'+ESC+'1 q'+'\x00'+'\r\n')
        out.flush()
        return 0
    finally:
        if old is not None:
            try: termios.tcsetattr(fd, termios.TCSADRAIN, old)
            except Exception: pass

def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    parsed=parse_args(argv)
    if parsed is None:
        sys.stderr.write("Invalid arguments\n"); return 1
    help_f, version_f, key_f, full_f, file = parsed
    if help_f:
        sys.stdout.write(HELP_TEXT); return 0
    if version_f:
        sys.stdout.write("1.4.1\n"); return 0
    if key_f:
        sys.stdout.write(KEY_TEXT); return 0
    if file is None:
        sys.stdout.write("Reading from stdin..."); sys.stdout.flush()
        text=sys.stdin.read()
    else:
        try:
            with open(file,'r',encoding='utf-8') as f: text=f.read()
        except Exception:
            sys.stderr.write(f"Could not open file {file}\n"); return 1
    try:
        data=load_json(text)
    except Exception as e:
        sys.stderr.write("\n"+nlohmannish_parse_error(text,e)+"\n"); return 1
    return interactive(data, full_f)

if __name__ == '__main__':
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        sys.exit(130)
